require_once __DIR__.'/../includes/bootstrap.php';if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);header('Allow: POST');exit('Metode tidak diizinkan.');}verify_csrf();$user=require_login();$workspaceId=filter_var($_POST['workspace_id']??null,FILTER_VALIDATE_INT);if(!$workspaceId){flash('error','Workspace tidak valid.');redirect('workspaces/index.php');}$st=$GLOBALS['pdo']->prepare('SELECT w.id FROM workspaces w JOIN workspace_members m ON m.workspace_id=w.id WHERE w.id=? AND m.user_id=? AND w.status="active" LIMIT 1');$st->execute([$workspaceId,$user['id']]);if(!$st->fetchColumn()){http_response_code(403);exit('Anda bukan anggota workspace ini.');}$_SESSION['workspace_id']=(int)$workspaceId;audit_log('workspace.switched','workspace',(int)$workspaceId);redirect('app/index.php');
